// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint balBeforeThis = address(this).balance;
        uint balBeforeC = address(c).balance;
        try c.deposit{value: amount}() {} catch { return; }
        vm.assume(address(c).balance == balBeforeC + amount);
        bool r1;
        uint thisAfter1;
        try c.withdrawAll() { r1 = false; thisAfter1 = address(this).balance; }
        catch { r1 = true; thisAfter1 = address(this).balance; }
        bool r2;
        uint thisAfter2;
        try c.withdrawAll() { r2 = false; thisAfter2 = address(this).balance; }
        catch { r2 = true; thisAfter2 = address(this).balance; }
        assertTrue(!r1 && !r2 && thisAfter2 == balBeforeThis && address(c).balance == balBeforeC);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
